def getResult(clockRecords):
    employees = {}
    ans = set()

    for i in range(len(clockRecords)):
        id, time, dis, act_device, reg_device = clockRecords[i]

        # 实际设备号与注册设备号不一样,则认为打卡异常
        if act_device != reg_device:
